#!/usr/bin/env bash
# Write the application's icon set from the brand's own drawings.
#
# It draws nothing. The identity has one home - MeshBench/brand, where every
# file is generated by marks.py - and a second description of the mark living
# here is how the two come to disagree. All this does is choose, for each size
# a desktop asks for, which of the brand's drawings is the right one, and
# rasterise it with rsvg-convert, which is what the brand's own build renders
# with.
#
# The choice matters more than it looks. The mark is drawn three times, not
# once and scaled: the greyed-back mesh behind the route turns to mush below
# about 24 pixels, so the small drawings shed it deliberately and keep every
# remaining element at least two pixels wide. Scaling the full drawing down to
# 16 is the one thing the brand names as never. A tile rather than a
# transparent mark, because a launcher, a dock and a task switcher all put an
# application icon on a background of their own choosing.
#
#	tools/icon.sh ../meshbench-brand
#
# The result is committed, because the brand repository is private and the
# packaging workflow cannot clone it. Rerun this when the brand changes.
set -euo pipefail

BRAND="${1:-${MESHBENCH_BRAND:-../meshbench-brand}}"
OUT="${2:-packaging/icons}"

if [ ! -f "$BRAND/logo/meshbench-appicon.svg" ]; then
  echo "icon: no brand checkout at $BRAND" >&2
  echo "pass it as the first argument, or set MESHBENCH_BRAND" >&2
  exit 1
fi
if ! command -v rsvg-convert >/dev/null; then
  echo "icon: rsvg-convert is not installed - it is librsvg, and it is what the brand renders with" >&2
  exit 1
fi

mkdir -p "$OUT"
# The sizes a Linux hicolor theme, a .desktop entry, an AppImage, a macOS
# iconset and a Windows .ico between them ask for.
for px in 16 24 32 48 64 128 256 512; do
  # The app icon carries the mark at compact weights, which holds down to 24.
  # The favicon tile carries the micro drawing, which is what 16 needs.
  src="$BRAND/logo/meshbench-appicon.svg"
  [ "$px" -lt 24 ] && src="$BRAND/logo/favicon-tile.svg"
  rsvg-convert "$src" -w "$px" -h "$px" -o "$OUT/meshbench-$px.png"
done

# The scalable entry, for Flathub and for any desktop that prefers it.
cp "$BRAND/logo/meshbench-appicon.svg" "$OUT/meshbench.svg"

echo "wrote $OUT: 8 PNGs and meshbench.svg, from $BRAND"
